class Solution { fun lengthOfLIS(nums:IntArray,k:Int):Int{val size=nums.maxOrNull()!!;val tree=IntArray(4*size+4);fun query(node:Int,left:Int,right:Int,ql:Int,qr:Int):Int{if(ql>right||qr<left)return 0;if(ql<=left&&right<=qr)return tree[node];val middle=(left+right)/2;return maxOf(query(node*2,left,middle,ql,qr),query(node*2+1,middle+1,right,ql,qr))};fun update(node:Int,left:Int,right:Int,index:Int,value:Int){if(left==right){tree[node]=maxOf(tree[node],value);return};val middle=(left+right)/2;if(index<=middle)update(node*2,left,middle,index,value)else update(node*2+1,middle+1,right,index,value);tree[node]=maxOf(tree[node*2],tree[node*2+1])};for(value in nums){var best=1;if(value>1)best+=query(1,1,size,maxOf(1,value-k),value-1);update(1,1,size,value,best)};return tree[1]} }
